105	// header_include eines Organs, wenn der Wrapper COMDARE_DEFINE_ORGAN_LOCATION traegt (HasOrganLocation<W>,
106	// INC-A #6). Wrapper OHNE per-Organ-Location liefern "" - eine Ableitung aus dem Typ-Namen waere
107	// fragil/fabriziert (die frueher bewusst leere 'header'-Emission, jetzt via Makro befuellt).
108	template <class W>
109	[[nodiscard]] std::string organ_header() {
110	    if constexpr (anat::HasOrganLocation<W>) {
111	        return std::string{W::header_include};
112	    } else {
113	        return std::string{};
114	    }
115	}
