150	// GUARD: kein clean serialize-Schluessel enthaelt '(' oder ' '. Faengt jede konditionale
151	// (disabled)/(real=std)-Form + versehentliche Family-Namen-Leaks. Leerer name ebenfalls illegal.
152	[[nodiscard]] bool name_is_clean(std::string const& n) {
153	    if (n.empty()) return false;
154	    return n.find('(') == std::string::npos && n.find(' ') == std::string::npos;
155	}
