72	[[nodiscard]] std::string short_name(std::string const& fq) {
73	    std::size_t const lt   = fq.find('<');
74	    std::string const head = (lt == std::string::npos) ? fq : fq.substr(0, lt);
75	    std::size_t const cc   = head.rfind("::");
76	    return (cc == std::string::npos) ? head : head.substr(cc + 2);
