79	[[nodiscard]] std::string xml_escape(std::string const& s) {
80	    std::string o;
81	    o.reserve(s.size());
82	    for (char const c : s) {
83	        switch (c) {
84	            case '&': o += "&amp;"; break;
85	            case '<': o += "&lt;"; break;
86	            case '>': o += "&gt;"; break;
87	            case '"': o += "&quot;"; break;
88	            case '\'': o += "&apos;"; break;
89	            default: o += c;
90	        }
91	    }
92	    return o;
93	}
